$('#pause').onclick=()=>{if(!game)return;paused=!paused;$('#pause').textContent=paused?'▶ Retomar':'Ⅱ Pausar';$('#message').style.display=paused?'grid':'none';if(paused)$('#message').innerHTML='<span>PAUSADO</span>';updateHud();if(net.host)broadcast({type:'pause',value:paused})};
function isWall(x,y,role){const tx=Math.floor(x/TILE),ty=Math.floor(y/TILE);if(ty<0||ty>=H||tx<0||tx>=W)return true;const c=game.grid[ty][tx];return c==='#'||(c==='-'&&role==='pac')}
function setDirection(a,dir){const d=DIRS[dir];if(d)a.want={x:d[0],y:d[1]}}
function nearestTarget(a){return game.actors.filter(p=>p.role!==a.role&&p.alive).sort((p,q)=>Math.hypot(p.x-a.x,p.y-a.y)-Math.hypot(q.x-a.x,q.y-a.y))[0]}
function aiMove(a){const tx=Math.floor(a.x/TILE),ty=Math.floor(a.y/TILE),cx=(tx+.5)*TILE,cy=(ty+.5)*TILE;if(Math.abs(a.x-cx)>2||Math.abs(a.y-cy)>2)return;const target=nearestTarget(a);if(!target)return;const options=Object.entries(DIRS).filter(([,d])=>!isWall(cx+d[0]*TILE,cy+d[1]*TILE,a.role));if(!options.length)return;const reverse={x:-a.dx,y:-a.dy};let choices=options.filter(([,d])=>d[0]!==reverse.x||d[1]!==reverse.y);if(!choices.length)choices=options;choices.sort(([,d1],[,d2])=>{const dist=d=>Math.hypot(target.x-(cx+d[0]*TILE),target.y-(cy+d[1]*TILE));return(a.role==='ghost'&&a.scared>0?1:-1)*(dist(d1)-dist(d2))});a.dx=choices[0][1][0];a.dy=choices[0][1][1]}
function moveActor(a,dt){if(!a.alive)return;if(a.ai)aiMove(a);const cx=(Math.floor(a.x/TILE)+.5)*TILE,cy=(Math.floor(a.y/TILE)+.5)*TILE,d=a.want;if((d.x||d.y)&&Math.abs(a.x-cx)<a.speed*dt+2&&Math.abs(a.y-cy)<a.speed*dt+2&&!isWall(cx+d.x*TILE,cy+d.y*TILE,a.role)){a.x=cx;a.y=cy;a.dx=d.x;a.dy=d.y}const nx=a.x+a.dx*a.speed*dt,ny=a.y+a.dy*a.speed*dt;if(!isWall(nx+a.dx*8,ny+a.dy*8,a.role)){a.x=nx;a.y=ny}else if(isWall(nx,ny,a.role)){a.dx=0;a.dy=0}if(a.x<-TILE/2)a.x=W*TILE;if(a.x>W*TILE)a.x=0}
function update(dt){if(!game||paused||game.over)return;game.time+=dt;for(const a of game.actors){if(a.role==='ghost'&&a.ai)aiMove(a);moveActor(a,dt);if(a.role==='pac'){const x=Math.floor(a.x/TILE),y=Math.floor(a.y/TILE),c=game.grid[y]?.[x];if(c==='.'||c==='o'){game.grid[y][x]=' ';game.remaining--;game.score+=c==='o'?50:10;if(c==='o')game.actors.filter(g=>g.role==='ghost').forEach(g=>g.scared=6)}}}
 for(const a of game.actors)if(a.scared>0)a.scared=Math.max(0,a.scared-dt);
 for(const g of game.actors.filter(a=>a.role==='ghost'&&a.alive))for(const p of game.actors.filter(a=>a.role==='pac'&&a.alive)){if(Math.hypot(p.x-g.x,p.y-g.y)<TILE*.7){if(g.scared){g.x=g.home.x;g.y=g.home.y;g.dx=g.dy=0;g.scared=0;game.score+=200}else p.alive=false}}
 if(!game.actors.some(a=>a.role==='pac'&&a.alive)){game.over=true;game.won=false}if(game.remaining<=0){game.over=true;game.won=true}if(game.over){$('#message').style.display='grid';$('#message').innerHTML=`<span>${game.won?'VOCÊ VENCEU!':'FIM DE JOGO'}<br><small style="font-size:.55em">Toque no labirinto ou espaço para recomeçar</small></span>`}updateHud();if(net.host&&performance.now()-net.lastSend>65){net.lastSend=performance.now();broadcast({type:'state',state:serializeGame()})}}
function render(){if(!game)return;ctx.fillStyle='#050914';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++){const c=game.grid[y][x],px=x*TILE,py=y*TILE;if(c==='#'){ctx.fillStyle='#111f45';ctx.fillRect(px,py,TILE,TILE);ctx.strokeStyle='#496dff';ctx.lineWidth=1.5;ctx.strokeRect(px+2,py+2,TILE-4,TILE-4)}else if(c==='-'){ctx.fillStyle='#cb65ff';ctx.fillRect(px,py+TILE/2-2,TILE,4)}else if(c==='.'||c==='o'){ctx.fillStyle=c==='o'?'#ffeb91':'#d5d9ec';ctx.beginPath();ctx.arc(px+TILE/2,py+TILE/2,c==='o'?5:2,0,Math.PI*2);ctx.fill()}}
 for(const a of game.actors){if(!a.alive)continue;ctx.save();ctx.translate(a.x,a.y);if(a.role==='pac'){const angle=Math.atan2(a.dy||0,a.dx||1),mouth=.18+Math.abs(Math.sin(game.time*9))*.27;ctx.fillStyle=a.color;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,10,angle+mouth,angle+Math.PI*2-mouth);ctx.closePath();ctx.fill();ctx.fillStyle='#171727';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText(a.name[0]?.toUpperCase()||'P',0,3)}else{ctx.fillStyle=a.scared?'#387dff':a.color;ctx.beginPath();ctx.arc(0,-1,10,Math.PI,0);ctx.lineTo(10,9);ctx.lineTo(5,6);ctx.lineTo(0,10);ctx.lineTo(-5,6);ctx.lineTo(-10,9);ctx.closePath();ctx.fill();ctx.fillStyle='white';ctx.beginPath();ctx.ellipse(-3,-1,2.4,3.3,0,0,Math.PI*2);ctx.ellipse(4,-1,2.4,3.3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#10172a';ctx.fillRect(-3,-1,2,2);ctx.fillRect(4,-1,2,2)}ctx.restore();ctx.fillStyle='#e3eaff';ctx.font='9px system-ui';ctx.textAlign='center';ctx.fillText(a.name,a.x,a.y-15)}}
function loop(t){raf=requestAnimationFrame(loop);if(!game)return;const dt=last?Math.min(.04,(t-last)/1000):0;last=t;if(!net.remote)update(dt);render()}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!game){return}if(k==='escape'||k==='p'){if(!net.remote)$('#pause').click();return}if(k===' '&&game.over){startGame();return}for(let i=0;i<roster.length;i++){const dir=Object.keys(KEYS[i%4]).find(d=>KEYS[i%4][d]===k);if(dir){const actor=game.actors.find(a=>a.slot===i&&!a.ai);if(actor){setDirection(actor,dir);if(net.remote)send({type:'input',slot:i,dir})}}}});
$$('.dpad button').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();if(game?.actors[0]){setDirection(game.actors[0],b.dataset.dir);if(net.remote)send({type:'input',slot:0,dir:b.dataset.dir})}}));
canvas.addEventListener('pointerdown',e=>{if(!game)return;if(game.over){startGame();return}const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width,y=(e.clientY-r.top)*canvas.height/r.height,a=game.actors.find(a=>a.slot===0&&!a.ai);if(!a)return;const dx=x-a.x,dy=y-a.y,dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');setDirection(a,dir);if(net.remote)send({type:'input',slot:0,dir})});
$('#mobile-action').onclick=()=>{if(game?.over)startGame();else $('#pause').click()};

