$('#mobile-action').onclick=()=>{if(game?.over)startGame();else $('#pause').click()};
function serializeGame(){return game?{grid:game.grid,actors:game.actors,score:game.score,remaining:game.remaining,time:game.time,over:game.over,won:game.won}:null}
function applyState(state){if(!state||!Array.isArray(state.grid)||!Array.isArray(state.actors))return;game={...state};updateHud();renderLegend();if(game.over){$('#message').style.display='grid';$('#message').innerHTML=`<span>${game.won?'VOCÊ VENCEU!':'FIM DE JOGO'}</span>`}else if(paused){$('#message').style.display='grid';$('#message').innerHTML='<span>PAUSADO</span>'}else $('#message').style.display='none'}
function send(data){if(net.conn?.open)net.conn.send(data)}
function broadcast(data){for(const conn of net.clients.keys())if(conn.open)conn.send(data)}
function roomStatus(text){$('#room-state').textContent=text}
function shortCode(){return Math.random().toString(36).slice(2,8).toUpperCase()}
function peerId(code){return`neonmaze-${code.toLowerCase().replace(/[^a-z0-9-]/g,'').slice(0,20)}`}
function stopNetwork(){try{net.conn?.close()}catch{}try{net.peer?.destroy()}catch{}net={peer:null,conn:null,host:false,remote:false,room:'',clients:new Map(),lastSend:0}}
function showGame(){ $('#menu-view').classList.add('hidden');$('#game-view').classList.add('active') }
function addOnlineActor(conn,info){if(!game||game.actors.filter(a=>!a.ai).length>=4){conn.send({type:'reject',reason:'A sala está cheia.'});conn.close();return}const slot=[0,1,2,3].find(i=>!game.actors.some(a=>a.slot===i&&!a.ai));if(slot===undefined){conn.send({type:'reject',reason:'A sala está cheia.'});conn.close();return}const role=info.role==='ghost'?'ghost':'pac',actor=makeActor(slot,{name:String(info.name||`Visitante ${slot+1}`).slice(0,14),role});actor.x=actor.home.x=role==='pac'?1.5*TILE:(9+(slot%3)+.5)*TILE;actor.y=actor.home.y=role==='pac'?15.5*TILE:9.5*TILE;game.actors.push(actor);net.clients.set(conn,slot);conn.send({type:'welcome',slot,room:net.room,state:serializeGame()});broadcast({type:'state',state:serializeGame()});renderLegend();toast(`${actor.name} entrou na sala.`)}
function handleHostMessage(conn,msg){if(!msg||typeof msg!=='object')return;if(msg.type==='hello'){addOnlineActor(conn,msg);return}const slot=net.clients.get(conn);if(msg.type==='input'&&slot!==undefined&&Number(msg.slot)===slot&&DIRS[msg.dir]){const actor=game?.actors.find(a=>a.slot===slot&&!a.ai);if(actor)setDirection(actor,msg.dir)}}
async function createRoom(){if(typeof Peer==='undefined'){toast('Não foi possível carregar o serviço online. Confira sua conexão.');return}stopNetwork();const code=shortCode();net.room=code;net.host=true;$('#room-id').value=code;roomStatus('Conectando…');$('#host').disabled=true;try{const peer=new Peer(peerId(code));net.peer=peer;peer.on('open',()=>{roomStatus(`Sala ${code} aberta — compartilhe o código e comece a jogar!`);$('#host').disabled=false;showGame();startGame();toast(`Sala ${code} criada.`)});peer.on('connection',conn=>{conn.on('data',msg=>handleHostMessage(conn,msg));conn.on('close',()=>{const slot=net.clients.get(conn);net.clients.delete(conn);if(game&&slot!==undefined){const a=game.actors.find(x=>x.slot===slot);if(a)a.alive=false;broadcast({type:'state',state:serializeGame()});renderLegend()}});conn.on('open',()=>{if(conn.peer)roomStatus(`Sala ${code} · jogador conectando…`)})});peer.on('error',err=>{console.error(err);roomStatus(err.type==='unavailable-id'?'Código ocupado. Tente criar outra sala.':'Falha na conexão. Tente novamente.');$('#host').disabled=false;toast('Não foi possível criar a sala.')})}catch(err){console.error(err);roomStatus('Falha ao criar a sala.');$('#host').disabled=false}}
function joinRoom(){if(typeof Peer==='undefined'){toast('Não foi possível carregar o serviço online. Confira sua conexão.');return}const code=$('#room-id').value.trim().toUpperCase();if(!/^[A-Z0-9-]{4,20}$/.test(code)){toast('Digite um código de sala válido.');return}stopNetwork();net.room=code;net.remote=true;roomStatus('Conectando à sala…');$('#join').disabled=true;const peer=new Peer();net.peer=peer;peer.on('open',()=>{const conn=peer.connect(peerId(code),{reliable:true});net.conn=conn;conn.on('open',()=>{const p=roster[0]||{name:'Jogador',role:'pac'};conn.send({type:'hello',name:p.name,role:p.role});roomStatus('Conectado — aguardando o estado da partida…')});conn.on('data',msg=>{if(!msg||typeof msg!=='object')return;if(msg.type==='welcome'){net.slot=msg.slot;showGame();applyState(msg.state);raf=requestAnimationFrame(loop);$('#join').disabled=false;roomStatus(`Na sala ${code} · você é ${roster[0]?.name||'Jogador'}`)}else if(msg.type==='state')applyState(msg.state);else if(msg.type==='pause'){paused=!!msg.value;updateHud()}else if(msg.type==='reject'){roomStatus(msg.reason);toast(msg.reason);stopNetwork();$('#join').disabled=false}});conn.on('close',()=>{if(net.remote){roomStatus('Conexão encerrada.');toast('A conexão com a sala foi encerrada.')}})});peer.on('error',err=>{console.error(err);roomStatus(err.type==='peer-unavailable'?'Sala não encontrada. Confira o código.':'Falha na conexão.');$('#join').disabled=false;net.remote=false})}
$('#host').onclick=createRoom;$('#join').onclick=joinRoom;$('#copy-room').onclick=async()=>{const code=$('#room-id').value.trim();if(!code){toast('Crie ou informe uma sala primeiro.');return}try{await navigator.clipboard.writeText(`${location.href.split('#')[0]}#sala=${encodeURIComponent(code)}`);toast('Convite copiado!')}catch{toast(`Código da sala: ${code}`)}};
function configureGoogle(){googleClientId=$('#google-client-id').value.trim();if(googleClientId)localStorage.setItem('neonGoogleClientId',googleClientId);if(!googleClientId){toast('Informe seu OAuth Client ID para ativar o Google.');$('#google-client-id').focus();return}if(!window.google?.accounts?.id){toast('Login Google ainda está carregando.');return}try{google.accounts.id.initialize({client_id:googleClientId,callback:credential=>{try{const payload=JSON.parse(atob(credential.credential.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));profile={name:payload.given_name||payload.name||payload.email.split('@')[0],email:payload.email};$('#account-name').textContent=profile.name;$('#google-button').textContent='Conectado';roster[0]={...(roster[0]||{}),name:profile.name};renderRoster();toast(`Olá, ${profile.name}!`)}catch{toast('Não foi possível ler o perfil Google.')}}});google.accounts.id.prompt()}catch(err){console.error(err);toast('Confira o Client ID e os domínios autorizados no Google Cloud.')}}
$('#google-button').onclick=configureGoogle;$('#google-client-id').value=googleClientId;$('#google-client-id').onchange=()=>{googleClientId=$('#google-client-id').value.trim();if(googleClientId)localStorage.setItem('neonGoogleClientId',googleClientId)};
const invite=new URLSearchParams(location.hash.slice(1));if(invite.has('sala')){$('#room-id').value=invite.get('sala');showMode('online')}
showMode('solo');renderRoster();
})();
</script></body></html>

